    imageAlt: `${drill.title} training drill photo`,
    youtubeUrl: `https://www.youtube.com/results?search_query=${encodeURIComponent(videoQuery)}`,
  };
}

export function searchAll(query = '') {
  const normalized = query.trim().toLowerCase();
  if (!normalized) {
    return { arts: martialArts, drills: [] };
  }
  const arts = martialArts.filter((art) => [art.name, art.description, art.family, art.origin, ...(art.tags || [])].join(' ').toLowerCase().includes(normalized));
  const matchedDrills = searchDrills({ query: normalized }).slice(0, 80);
  return { arts, drills: matchedDrills };
}

export function getArtProfile(id) {
  const art = martialArts.find((item) => item.id === id) || martialArts[0];
  const artDrills = drills.filter((d) => d.martialArts.includes(art.id) || (d.compatibleArts || []).includes(art.id));
  const categoryCounts = categories.map((category) => ({ ...category, count: artDrills.filter((d) => d.primaryCategory === category.id).length })).filter((c) => c.count > 0);
  return { ...art, drills: artDrills, categoryCounts };
}
